import fs from "node:fs";
const runtime = fs.readFileSync(
  "supabase/functions/_shared/runtime.ts",
  "utf8",
);
const validation = fs.readFileSync(
  "supabase/functions/_shared/carousel.ts",
  "utf8",
);
const endpoint = fs
  .readFileSync("supabase/functions/carousel/index.ts", "utf8")
  .replace(
    /import[\s\S]*?from "\.\.\/_shared\/(?:runtime|carousel)\.ts";\n/g,
    "",
  );
const output =
  "// Generated by node scripts/prepare-carousel-dashboard.mjs.\n// Copy this entire file into a Supabase dashboard function named carousel.\n// No credentials are embedded. Authentication is enforced in the handler.\n\n" +
  runtime +
  "\n" +
  validation +
  "\n" +
  endpoint;
const path = "review/carousel-dashboard.ts";
if (process.argv.includes("--check")) {
  if (fs.readFileSync(path, "utf8") !== output)
    throw new Error(
      "Regenerate the dashboard carousel function before deploying.",
    );
} else {
  fs.mkdirSync("review", { recursive: true });
  fs.writeFileSync(path, output);
}
